import 'package:cloud_firestore/cloud_firestore.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:flutter/material.dart';import '../services/auth_service.dart';import '../utils/app_colors.dart';import 'login_page.dart';
class ProfilePage extends StatelessWidget{
 const ProfilePage({super.key});
 @override Widget build(BuildContext context){final user=FirebaseAuth.instance.currentUser;if(user==null)return const Center(child:Text('Pengguna belum login.'));
 final userRef=FirebaseFirestore.instance.collection('users').doc(user.uid);
 return Scaffold(backgroundColor:AppColors.background,appBar:AppBar(title:const Text('Profil')),
 body:StreamBuilder<DocumentSnapshot<Map<String,dynamic>>>(stream:userRef.snapshots(),builder:(context,s){if(s.hasError)return const Center(child:Text('Gagal memuat profil.'));if(!s.hasData)return const Center(child:CircularProgressIndicator());final data=s.data!.data()??{};final name=(data['name']??user.displayName??'Pengguna LabTrack').toString();final kelas=(data['kelas']??'-').toString();final email=(data['email']??user.email??'-').toString();
 return ListView(padding:const EdgeInsets.fromLTRB(18,8,18,30),children:[
 Container(padding:const EdgeInsets.all(23),decoration:BoxDecoration(gradient:const LinearGradient(colors:[AppColors.primary,AppColors.secondary]),borderRadius:BorderRadius.circular(24)),child:Column(children:[
 CircleAvatar(radius:43,backgroundColor:Colors.white,child:Text(name.isEmpty?'U':name.substring(0,1).toUpperCase(),style:const TextStyle(color:AppColors.primary,fontSize:30,fontWeight:FontWeight.bold))),
 const SizedBox(height:13),Text(name,style:const TextStyle(color:Colors.white,fontSize:21,fontWeight:FontWeight.bold)),const SizedBox(height:5),Text(kelas,style:const TextStyle(color:Colors.white70)),const SizedBox(height:16),
 OutlinedButton.icon(onPressed:()=>_editProfile(context,userRef,user,name,kelas),icon:const Icon(Icons.edit_outlined,size:18),label:const Text('Edit profil'),style:OutlinedButton.styleFrom(foregroundColor:Colors.white,side:const BorderSide(color:Colors.white70),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(14))))
 ])),
 const SizedBox(height:22),const Text('Informasi akun',style:TextStyle(fontSize:17,fontWeight:FontWeight.bold,color:AppColors.navy)),const SizedBox(height:10),
 _info(Icons.person_outline,'Nama',name),_info(Icons.school_outlined,'Kelas',kelas),_info(Icons.email_outlined,'Email',email),
 const SizedBox(height:22),const Text('Riwayat peminjaman',style:TextStyle(fontSize:17,fontWeight:FontWeight.bold,color:AppColors.navy)),const SizedBox(height:10),
 StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:userRef.collection('borrowings').orderBy('borrow_date',descending:true).snapshots(),builder:(context,h){if(h.hasError)return const Text('Gagal memuat riwayat peminjaman.');if(!h.hasData)return const Center(child:CircularProgressIndicator());final docs=h.data!.docs;if(docs.isEmpty)return Container(padding:const EdgeInsets.all(25),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(18)),child:const Column(children:[Icon(Icons.history,color:AppColors.muted,size:38),SizedBox(height:8),Text('Belum ada riwayat peminjaman.',style:TextStyle(color:AppColors.muted))]));return Column(children:docs.map((doc){final d=doc.data();final raw=d['borrow_date'];final date=raw is Timestamp?MaterialLocalizations.of(context).formatMediumDate(raw.toDate()):'Tanggal sedang diproses';final item=(d['item_name']??'Barang').toString();final code=(d['item_code']??'').toString();final status=(d['status']??'Dipinjam').toString();return Container(margin:const EdgeInsets.only(bottom:10),padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(17)),child:Row(children:[Container(width:42,height:42,decoration:BoxDecoration(color:AppColors.primary.withValues(alpha:.09),borderRadius:BorderRadius.circular(13)),child:const Icon(Icons.inventory_2_outlined,color:AppColors.primary)),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(item,style:const TextStyle(fontWeight:FontWeight.bold,color:AppColors.navy)),if(code.isNotEmpty)Text(code,style:const TextStyle(color:AppColors.muted,fontSize:11)),Text('Dipinjam pada '+date,style:const TextStyle(color:AppColors.muted,fontSize:11))])),Container(padding:const EdgeInsets.symmetric(horizontal:9,vertical:5),decoration:BoxDecoration(color:AppColors.borrowed.withValues(alpha:.1),borderRadius:BorderRadius.circular(20)),child:Text(status,style:const TextStyle(color:AppColors.borrowed,fontSize:10,fontWeight:FontWeight.bold)))]));}).toList());}),
 const SizedBox(height:20),SizedBox(width:double.infinity,height:50,child:OutlinedButton.icon(onPressed:()=>_logout(context),icon:const Icon(Icons.logout),label:const Text('Logout'),style:OutlinedButton.styleFrom(foregroundColor:AppColors.primary,side:const BorderSide(color:AppColors.primary),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(15)))))
 ]);
 }));
 }
 Widget _info(IconData icon,String title,String value)=>Container(margin:const EdgeInsets.only(bottom:9),padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(15)),child:Row(children:[Icon(icon,color:AppColors.primary),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(color:AppColors.muted,fontSize:11)),const SizedBox(height:3),Text(value,style:const TextStyle(color:AppColors.text,fontWeight:FontWeight.w600))]))]));
 Future<void> _editProfile(BuildContext context,DocumentReference<Map<String,dynamic>> ref,User user,String name,String kelas)async{final n=TextEditingController(text:name);final k=TextEditingController(text:kelas=='-'?'':kelas);final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('Edit profil'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Nama lengkap')),const SizedBox(height:12),TextField(controller:k,decoration:const InputDecoration(labelText:'Kelas'))]),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Batal')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Simpan'))]));if(ok==true&&n.text.trim().isNotEmpty){try{await ref.update({'name':n.text.trim(),'kelas':k.text.trim()});await user.updateDisplayName(n.text.trim());if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Profil berhasil diperbarui.')));}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Gagal memperbarui profil: $e')));}}n.dispose();k.dispose();}
 Future<void> _logout(BuildContext context)async{final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('Logout'),content:const Text('Yakin ingin keluar dari akun?'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Batal')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Logout'))]));if(ok==true){await AuthService().logout();if(!context.mounted)return;Navigator.pushAndRemoveUntil(context,MaterialPageRoute(builder:(_)=>const LoginPage()),(route)=>false);}}
}
